import { FileTextIcon } from "@/components/icons";
import { AccordionItem } from "@/components/ui/Accordion";
import type { RetrievedChunk } from "@/types";

export function RetrievedChunks({ chunks }: { chunks: RetrievedChunk[] }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "0.75rem" }}>
      {chunks.map((chunk) => (
        <AccordionItem
          key={chunk.id}
          header={
            <div style={{ display: "flex", minWidth: 0, alignItems: "center", gap: "0.75rem" }}>
              <FileTextIcon size={16} style={{ flexShrink: 0, color: "var(--purple)" }} />
              <div style={{ minWidth: 0 }}>
                <p className="truncate" style={{ fontSize: "0.875rem", fontWeight: 500, color: "#374151" }}>
                  {chunk.sourceFile}
                </p>
                <p style={{ fontSize: "0.75rem", color: "var(--text-faint)" }}>
                  Similarity {Math.round(chunk.similarity * 100)}%
                </p>
              </div>
            </div>
          }
        >
          {chunk.text}
        </AccordionItem>
      ))}
    </div>
  );
}
