"use client";

import { useState } from "react";
import { SearchIcon, SparklesIcon } from "@/components/icons";
import { AppShell } from "@/components/shared/AppShell";
import { Input } from "@/components/ui/Input";
import { Button } from "@/components/ui/Button";
import { Card } from "@/components/ui/Card";
import { LoadingScreen } from "@/components/ui/LoadingScreen";
import { EmptyState } from "@/components/ui/EmptyState";
import { Timeline } from "@/components/planner/Timeline";
import { RetrievedChunks } from "@/components/planner/RetrievedChunks";
import { useStudyPlan } from "@/hooks/useStudyPlan";

export default function PlannerPage() {
  const [topic, setTopic] = useState("");
  const { plan, isGenerating, generate } = useStudyPlan();

  async function handleGenerate() {
    if (!topic.trim()) return;
    await generate(topic.trim());
  }

  return (
    <AppShell title="Study Planner">
      <Card hoverLift={false} softBg>
        <div className="planner-hero">
          <span className="planner-badge">
            <SparklesIcon size={14} /> Powered by retrieval-augmented generation
          </span>
          <div className="planner-search">
            <Input
              icon={<SearchIcon size={16} />}
              placeholder="What topic do you want to study?"
              value={topic}
              onChange={(e) => setTopic(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleGenerate()}
              inputSize="lg"
            />
          </div>
          <Button size="lg" onClick={handleGenerate} isLoading={isGenerating} disabled={!topic.trim()}>
            <SparklesIcon size={18} /> Generate Study Plan
          </Button>
        </div>
      </Card>

      <div className="mt-8">
        {isGenerating && <LoadingScreen />}

        {!isGenerating && !plan && (
          <EmptyState
            icon={<SparklesIcon size={24} />}
            title="No study plan yet"
            description="Enter a topic above and we'll build a personalized day-by-day plan from your uploaded notes."
          />
        )}

        {!isGenerating && plan && (
          <div style={{ display: "flex", flexDirection: "column", gap: "2rem" }}>
            <div>
              <h2 className="plan-heading">Your plan for &ldquo;{plan.topic}&rdquo;</h2>
              <p className="plan-subheading">
                {plan.days.length} days, built from {plan.retrievedChunks.length} retrieved passages.
              </p>
            </div>

            <Timeline days={plan.days} />

            <div>
              <h3 className="section-title">Retrieved Chunks</h3>
              <RetrievedChunks chunks={plan.retrievedChunks} />
            </div>
          </div>
        )}
      </div>
    </AppShell>
  );
}
