"use client";

import { ReactNode, useState } from "react";
import { ChevronDownIcon } from "@/components/icons";
import { cn } from "@/lib/utils";

interface AccordionItemProps {
  header: ReactNode;
  children: ReactNode;
  defaultOpen?: boolean;
}

export function AccordionItem({ header, children, defaultOpen = false }: AccordionItemProps) {
  const [open, setOpen] = useState(defaultOpen);

  return (
    <div className="accordion-item">
      <button
        onClick={() => setOpen((o) => !o)}
        className="accordion-header"
        aria-expanded={open}
      >
        {header}
        <ChevronDownIcon size={16} className={cn("accordion-chevron", open && "accordion-chevron--open")} />
      </button>
      <div className={cn("accordion-body", open && "accordion-body--open")}>
        <div className="accordion-body-inner">{children}</div>
      </div>
    </div>
  );
}
