"use client";

import { useCallback, useState } from "react";
import type { StudyPlan } from "@/types";
import { generateStudyPlan } from "@/services/api";
import { useToast } from "@/components/ui/Toast";

export function useStudyPlan() {
  const [plan, setPlan] = useState<StudyPlan | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const toast = useToast();

  const generate = useCallback(
    async (topic: string) => {
      setIsGenerating(true);
      setError(null);
      try {
        const result = await generateStudyPlan(topic);
        setPlan(result);
        toast.success("Study plan ready");
        return result;
      } catch {
        setError("Couldn't generate a study plan. Try again.");
        toast.error("Something went wrong generating your plan");
        return null;
      } finally {
        setIsGenerating(false);
      }
    },
    [toast]
  );

  const reset = useCallback(() => setPlan(null), []);

  return { plan, isGenerating, error, generate, reset };
}
