import { ClockIcon, TargetIcon, BookOpenIcon } from "@/components/icons";
import { Card } from "@/components/ui/Card";
import { cn } from "@/lib/utils";
import type { StudyDay } from "@/types";

const difficultyBadge: Record<StudyDay["difficulty"], string> = {
  Beginner: "badge badge--success",
  Intermediate: "badge badge--warning",
  Advanced: "badge badge--danger",
};

export function StudyPlanCard({ day }: { day: StudyDay; index: number }) {
  return (
    <Card>
      <div className="plan-card-top">
        <span className="plan-day-eyebrow">Day {day.day}</span>
        <span className={cn(difficultyBadge[day.difficulty])}>{day.difficulty}</span>
      </div>

      <h4 className="plan-topic">{day.topics[0]}</h4>
      {day.topics[1] && <p className="plan-topic-secondary">{day.topics[1]}</p>}

      <div className="plan-meta-list">
        <div className="plan-meta-row">
          <TargetIcon size={14} />
          <span>{day.objectives.join(" · ")}</span>
        </div>
        <div className="plan-meta-row">
          <ClockIcon size={14} />
          <span>{day.estimatedTime}</span>
        </div>
        <div className="plan-meta-row">
          <BookOpenIcon size={14} />
          <span>{day.resources.join(", ")}</span>
        </div>
      </div>
    </Card>
  );
}
